# May 2025
# This R script rationalizes and rounds the figures/estimates created in the upstream R scripts so that they conform with the guidelines for the DfE Exploring
# Education Statistics production platform system. This script covers three areas of GLMS, including employment rates, skilled employment rates and 
# yearly salaries. Outputs generated by the script include a data file and meta- data file.


######################################
# Time series and skilled employment #
######################################

# Read in rds output files
Employment_rates_original <- readRDS(paste0(filepath,data_folder,start_year,"_",end_year,".rds"))

Skilled_emp_rates_original <- readRDS(paste0(filepath,data_folder,end_year,".rds"))

Yearly_salaries_original <- readRDS(paste0(filepath, data_folder,start_year,"_",end_year,".rds"))



#### Employment rates

# Creates new columns for EES standards - time and geography
# Renames columns
Employment_rates <- Employment_rates_original %>%
  mutate(time_identifier = "Calendar year",
         geographic_level = "National",
         country_code = "E92000001",
         country_name = "England") %>%
  rename(time_period = Year,
         age_group = Age_range,
         graduate_type = Population,
         hs_employment_rate = HSemployment_rate,
         hs_employed_sample = HSemployed_sample,
         hs_employment_accuracy_flag = HSemployment_accuracy_flag,
         hs_employment_suppression_flag = HSemployment_suppression_flag)

# Makes all column names lower case
colnames(Employment_rates) <- tolower(colnames(Employment_rates))

# Tweak the names of the various accuracy flags to make them more descriptive / useful - March 2025 edit
Employment_rates <- Employment_rates %>%
mutate(employment_rate_accuracy = employment_accuracy_flag) %>%
mutate(hs_employment_rate_accuracy = hs_employment_accuracy_flag) %>%
mutate(unemployment_rate_accuracy = unemployment_accuracy_flag) %>%  
mutate(inactivity_rate_accuracy = inactive_accuracy_flag) %>%
mutate(employment_rate_suppression = employment_suppression_flag) %>%
mutate(hs_employment_rate_suppression = hs_employment_suppression_flag) %>%
mutate(unemployment_rate_suppression = unemployment_suppression_flag) %>%  
mutate(inactivity_rate_suppression = inactive_suppression_flag) %>%
mutate(age_band = age_group) %>%  # changed to age_band for consitency across the EES scripts
  # Select the variables needed and reorder
# Employment_rates <- Employment_rates %>%
  select("time_period",
         "time_identifier",
         "geographic_level",
         "country_code",
         "country_name",
         "age_band",
         "graduate_type",
         "employment_rate",
         "hs_employment_rate",
         "unemployment_rate",
         "inactivity_rate",
         "employment_rate_accuracy",
         "hs_employment_rate_accuracy",
         "unemployment_rate_accuracy",
         "inactivity_rate_accuracy",
         "employment_rate_suppression",
         "hs_employment_rate_suppression",
         "unemployment_rate_suppression",
         "inactivity_rate_suppression")
  

# Ungroups data (that was previously grouped using group_by function)
# Filters out all cases wheregraduate type is not in scope
Employment_rates <- Employment_rates %>%
  ungroup() %>%
  filter(!graduate_type == "Not in scope")

# Multiplies rates by 100 and rounds to one decimal place
Employment_rates <- Employment_rates %>%
  mutate(employment_rate = employment_rate*100) %>%
  mutate(hs_employment_rate = hs_employment_rate*100) %>%
  mutate(unemployment_rate = unemployment_rate*100) %>% 
  mutate(inactivity_rate = inactivity_rate*100) %>%
  mutate(employment_rate = formatC(employment_rate, digits = 1, format = "f")) %>%
  mutate(hs_employment_rate = formatC(hs_employment_rate, digits = 1, format = "f")) %>%
  mutate(unemployment_rate = formatC(unemployment_rate, digits = 1, format = "f")) %>%
  mutate(inactivity_rate = formatC(inactivity_rate, digits = 1, format = "f"))
  
# Revalue some of the values in the graduate_type
Employment_rates <- Employment_rates %>%
  mutate(graduate_type = recode(graduate_type, 
                                "Non grad" = "Non-graduate",
                                "Post grad" = "Postgraduate"))

# remove the suppression flags as have no value to the output file - first
# check that no suppression is actually needed to be applied here
# Employment_rates <- Employment_rates %>%
#  select(-c(employment_rate_suppression, unemployment_rate_suppression,
#           inactivity_rate_suppression, hs_employment_rate_suppression))

readr::write_csv(Employment_rates,
                 paste0(filepath, data_folder,label_EES,".csv"))


# Make a table for the meta data

Employment_rates.meta <- data.frame("col_name" = c("employment_rate",
                                                   "hs_employment_rate",
                                                   "unemployment_rate",
                                                   "inactivity_rate",
                                                   "age_band",
                                                   "graduate_type"),
                                    "col_type" = c("Indicator",
                                                   "Indicator",
                                                   "Indicator",
                                                   "Indicator",
                                                   "Filter",
                                                   "Filter"),
                                    "label" = c("Employment rate",
                                                "High-skilled employment rate",
                                                "Unemployment rate",
                                                "Inactivity rate",
                                                "Age band",
                                                "Graduate type"),
                                    "indicator_grouping" = c("","", "","","",""),
                                    "indicator_unit" = c("%","%","%","%","",""),
                                    "indicator_dp"= c("1","1", "1","1","",""),
                                    "filter_hint" = c("", "","","","Select the Age band you are interested in","Select the Graduate type you are interested in"),
                                    "filter_grouping_column"=c("","","","","",""))

readr::write_csv(Employment_rates.meta,
          paste0(filepath, data_folder,label_EES,".meta.csv"))







