#### Salaries

# Creates new columns for EES standards - time and geography
# Renames columns
Yearly_salaries <- Yearly_salaries_original %>%
  mutate(time_identifier = "Calendar year",
         geographic_level = "National",
         country_code = "E92000001",
         country_name = "England") %>%
  rename(time_period = Year,
         age_group = AGE_BANDS,
         sex = SEX)

# Makes all column names lower case
colnames(Yearly_salaries) <- tolower(colnames(Yearly_salaries))
# Rename accuracy flag to something more descriptive / useful i.e. median_salary_accuracy
Yearly_salaries <- Yearly_salaries %>%
mutate(median_salary_accuracy = accuracy_flag) %>%  
mutate(median_salary_suppression = suppression_flag) %>%  
mutate(age_band = age_group) %>%  
  #Select the variables needed
# Yearly_salaries <- Yearly_salaries %>%
  select("time_period",
         "time_identifier",
         "geographic_level",
         "country_code",
         "country_name",
         "age_band", # changed to age_band for wider consistency across the 3 EES scripts
         "graduate_type",
         "sex",
         "median",
         "median_real",
         "median_salary_accuracy", # replacing accuracy_flag here in the data frame to write to file
         "median_salary_suppression") # same as above for the suppression flag

#Change Median salaries to be the yearly median salary,then Round up the median salaries to the nearest £500. See data assumptions
#log for the rounding convention
Yearly_salaries <- Yearly_salaries %>%
  mutate(median = ifelse(leap_year(time_period), median*366/7, median*365/7))  %>%
  mutate(p = median%%500) %>%  
  mutate(rd_up = median+500-p) %>% #Numbers for rounding up
  mutate(rd_down = median-p) %>%   #Numbers for rounding down
  mutate(median = ifelse(500-p<=p,rd_up,rd_down)) %>%
  mutate(median_real = ifelse(leap_year(time_period), median_real*366/7, median_real*365/7))  %>%
  mutate(p = median_real%%500) %>%
  mutate(rd_up = median_real+500-p) %>% #Numbers for rounding up
  mutate(rd_down = median_real-p)%>%   #Numbers for rounding down
  mutate(median_real = ifelse(500-p<=p, rd_up, rd_down)) #decision on rounding

#Remove surplus columns
Yearly_salaries <- Yearly_salaries[,-(13:15), drop = FALSE]

# Retains only the ages we report on
Yearly_salaries <- Yearly_salaries %>%
  filter(age_band == "21-30" | age_band == "Total") # changed to age_band for wider consistency

# Rename values
Yearly_salaries <- Yearly_salaries %>%
  mutate(age_band = recode(age_band, 
                            "Total" = "16-64",
                            "21-30" = "21-30")) %>% # changing to age_band as above
  mutate(sex = recode(sex, 
                         "All" = "Total"))
  

# Filters out all cases where graduate type is not in scope
# Revalue some of the values in the graduate_type
Yearly_salaries <- Yearly_salaries %>%
  filter(!graduate_type == "Not in scope") %>% 
  
  mutate(graduate_type = recode(graduate_type, 
                                "Non grad" = "Non-graduate",
                                "Post grad" = "Postgraduate"))


  # remove the suppression flags as have no value to the output file - first
  # check that no suppression is actually needed to be applied here
#  Yearly_salaries <- Yearly_salaries %>%
#  select(-(median_salary_suppression)) 

# Save CSV
readr::write_csv(Yearly_salaries,
          paste0(filepath, data_folder,label_EES,".csv"))

# Make a table for the meta data

 Yearly_salaries_by_sex.meta <- data.frame("col_name" = c("median", "median_real","age_band","graduate_type","sex"),
                                             "col_type" = c("Indicator", "Indicator","Filter","Filter","Filter"),
                                             "label" = c("Median annual salary to the nearest £500", "Median annual salary to the nearest £500 in real (2007) terms",
                                                         "Age band", "Graduate type","Sex"),
                                             "indicator_grouping" = c("","","","",""),
                                             "indicator_unit" = c("£","£","","",""),
                                             "indicator_dp" = c("","","","",""),
                                             "filter_hint" = c("","","Select the Age band you are interested in","Select the Graduate Type you are interested in","Select the Sex you are interested in"),
                                             "filter_grouping_column" = c("","","","",""))
                                             



# Fixes encoding issue, with strange character
 Yearly_salaries_by_sex.meta <- as.data.frame(sapply(Yearly_salaries_by_sex.meta, function(x) gsub("Â£", "£", x)))

